// GitHub fires this webhook for many event types. Filter to:
//   - pull_request.closed events
//   - merged === true
//   - base.ref === 'master' (don't update Notion for non-prod merges)
//   - head.ref starts with 'content/' (only content engine PRs map to Notion topics)
// Also extracts the post slug from the branch name and builds the canonical
// public URL, which downstream IndexNow / Google Indexing nodes consume.
const config = $('Config').first().json;
const payload = $('GitHub Webhook').first().json.body || {};

const action = payload.action;
const pr = payload.pull_request || {};
const merged = pr.merged === true;
const baseRef = pr.base?.ref;
const headRef = pr.head?.ref || '';
const prUrl = pr.html_url;

const eligible =
  action === 'closed' &&
  merged &&
  baseRef === 'master' &&
  headRef.startsWith('content/') &&
  !!prUrl;

if (!eligible) {
  console.log(`Webhook skipped: action=${action} merged=${merged} baseRef=${baseRef} headRef=${headRef}`);
  return [];
}

// Branch convention: content/<slug>. The slug equals the .mdx filename without
// extension, which is also the URL slug under /blog/<slug>/.
const slug = headRef.replace(/^content\//, '');
const postUrl = `https://${config.siteHost}/blog/${slug}/`;

return [{ json: { ...config, prUrl, prTitle: pr.title, prNumber: pr.number, mergedAt: pr.merged_at, slug, postUrl } }];

// Pull the matched Notion page ID. If no match, abort gracefully — the PR
// might be a non-engine content commit or the calendar entry was deleted.
const meta = $('Filter Eligible').first().json;
const response = $input.first().json;
const page = (response.results || [])[0];

if (!page) {
  console.log(`No Notion topic found with PR URL ${meta.prUrl}. Skipping status update.`);
  return [];
}

return [{ json: { ...meta, topicPageId: page.id } }];

// Gate the Google Indexing API branch on the service-account JSON being
// populated. If empty, return [] to short-circuit the rest of the chain
// — this keeps the workflow shippable before Ian sets up the GCP side.
const data = $('Resolve Page').first().json;
const sa = (data.googleServiceAccountJson || '').trim();

if (!sa) {
  console.log('googleServiceAccountJson is empty — skipping Google Indexing API submit. To enable: paste the service account JSON into the Config node\'s googleServiceAccountJson field after granting it Owner on the GSC property.');
  return [];
}

let parsed;
try {
  parsed = JSON.parse(sa);
} catch (err) {
  console.log(`googleServiceAccountJson is set but not valid JSON: ${err.message}. Skipping.`);
  return [];
}

if (!parsed.client_email || !parsed.private_key) {
  console.log('googleServiceAccountJson is valid JSON but missing client_email or private_key. Skipping.');
  return [];
}

return [{ json: { ...data, _saClientEmail: parsed.client_email, _saPrivateKey: parsed.private_key } }];

// Build a signed JWT for Google's OAuth2 token endpoint, using the service
// account's RSA private key (RS256). No external dependencies — we use
// Node's built-in crypto module, which n8n's Code node exposes.
const crypto = require('crypto');
const data = $input.first().json;
const clientEmail = data._saClientEmail;
const privateKey = data._saPrivateKey;

const b64url = (input) =>
  Buffer.from(input).toString('base64').replace(/=+$/, '').replace(/\+/g, '-').replace(/\//g, '_');

const header = b64url(JSON.stringify({ alg: 'RS256', typ: 'JWT' }));
const now = Math.floor(Date.now() / 1000);
const payload = b64url(JSON.stringify({
  iss: clientEmail,
  scope: 'https://www.googleapis.com/auth/indexing',
  aud: 'https://oauth2.googleapis.com/token',
  iat: now,
  exp: now + 3600,
}));

const signingInput = `${header}.${payload}`;
const signature = crypto
  .createSign('RSA-SHA256')
  .update(signingInput)
  .sign(privateKey)
  .toString('base64')
  .replace(/=+$/, '')
  .replace(/\+/g, '-')
  .replace(/\//g, '_');

const jwt = `${signingInput}.${signature}`;

// Drop the private key from the carried payload so it doesn't leak into
// downstream node-logging or HTTP request inspectors.
const { _saPrivateKey, _saClientEmail, googleServiceAccountJson, ...rest } = data;
return [{ json: { ...rest, jwt } }];
